mapper.update:
update TASK_ACT_ASSIGNEE ass


        ass.ASS_STATE = #{assState},


        ass.ASS_MODIFY_TM = #{assModifyTm}


where 1=1

    and ass.ASS_ACT_ID = #{assActId}


    and ass.ASS_ID = #{assId}

mapper.select:
select ASS_ID as assId, ASS_MOBILE as assMobile, ASS_ASSIGNEE as assAssignee from TASK_ACT_ASSIGNEE ass where ass.ASS_STATE!='03'
and ass.ASS_ACT_ID = #{actId}
and ass.ASS_ID = #{assId}
